import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import type { Event } from '../../lib/event-log.js';
import { EVENTS_PATH } from '../../lib/event-log.js';
import { childrenDir } from '../../lib/children-bus.js';

/**
 * Read every event in the active log. Test-grade replacement for the retired
 * `readEventsSince(null)`: whole-file read, no cursors, no chunking — tests
 * work on small fixture logs where that machinery was untested weight.
 */
export function readAllEvents(): Event[] {
  const path = process.env.ORK_EVENTS_LOG || EVENTS_PATH;
  let raw: string;
  try {
    raw = readFileSync(path, 'utf8');
  } catch {
    // silent: best-effort — a missing log in a test simply means "no events yet"
    return [];
  }
  const out: Event[] = [];
  for (const line of raw.split('\n')) {
    if (!line) continue;
    try {
      out.push(JSON.parse(line) as Event);
    } catch {
      // silent: known-noise — mirrors the retired reader, malformed lines skip
    }
  }
  return out;
}

/** Seed a child-state file the way the retired writeChildState did. */
export function writeChildState(parentDir: string, sid: string, payload: object): void {
  const dir = childrenDir(parentDir);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, `${sid}.json`), JSON.stringify(payload));
}

/** Read a child-state file back; null when absent or corrupt. */
export function readChildState(parentDir: string, sid: string): object | null {
  const target = join(childrenDir(parentDir), `${sid}.json`);
  if (!existsSync(target)) return null;
  try {
    return JSON.parse(readFileSync(target, 'utf8')) as object;
  } catch {
    // silent: best-effort — corrupt fixture reads as absent, as the original did
    return null;
  }
}
